// Builds the "Sync to Cookin" bookmark button.
//   node tools/bookmarklet/build.mjs          write src/features/nyt-sync/bookmarklet.generated.ts
//   node tools/bookmarklet/build.mjs --check  fail if the generated file is out of date
import { build } from "esbuild";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("../../", import.meta.url));
export const PLACEHOLDER = "__COOKIN_APP_ORIGIN__";

export async function bundle() {
  const out = await build({
    entryPoints: [root + "tools/bookmarklet/entry.ts"],
    bundle: true, minify: true, write: false, format: "iife", target: "es2020", charset: "utf8",
    define: { __COOKIN_APP__: JSON.stringify(PLACEHOLDER) },
    legalComments: "none",
  });
  return out.outputFiles[0].text.trim();
}

const target = root + "src/features/nyt-sync/bookmarklet.generated.ts";
// The button keeps a copy of itself in cooking.nytimes.com's localStorage ("cookin-button") so the
// weekly automation can start it with a one-line script instead of pasting the whole bundle.
const code = `(function cookinButton(){try{localStorage.setItem("cookin-button","("+cookinButton+")()")}catch(e){}${await bundle()}})()`;
const file = `// Generated by tools/bookmarklet/build.mjs. Do not edit; run \`npm run build:bookmarklet\`.\n` +
  `export const BOOKMARKLET_PLACEHOLDER = ${JSON.stringify(PLACEHOLDER)};\n` +
  `export const BOOKMARKLET_CODE = ${JSON.stringify(code)};\n`;
if (process.argv.includes("--check")) {
  const cur = existsSync(target) ? readFileSync(target, "utf8") : "";
  if (cur !== file) { console.error("bookmarklet.generated.ts is out of date: run npm run build:bookmarklet"); process.exit(1); }
  console.log("bookmarklet up to date");
} else {
  writeFileSync(target, file);
  console.log(`bookmarklet: ${code.length} bytes`);
}
